#!/bin/sh
# Independent official bootstrap. Generated with the audited release verifier and roots.
set -eu
PATH=/usr/sbin:/usr/bin:/sbin:/bin:/usr/local/sbin:/usr/local/bin
export PATH
umask 077

if [ "${1:-}" = --help ]; then
  printf '%s\n' '用法: bootstrap.sh --panel https://面板 --token 接入令牌 --version latest或版本 --target auto或平台'
  exit 0
fi
if [ "$(id -u)" != 0 ]; then
  echo '请以 root 执行此脚本，或使用面板提供的官方单行安装入口。' >&2
  exit 1
fi
PLATFORM=$(uname -s)
case "$PLATFORM" in
  Linux)
    STAGING_BASE=/opt/apsp
    if [ -d /run/systemd/system ] && command -v systemctl >/dev/null; then :
    elif [ -f /run/openrc/softlevel ] && command -v rc-service >/dev/null && command -v rc-update >/dev/null; then :
    else echo 'Linux 接入需要运行中的 systemd 或 OpenRC' >&2; exit 1; fi
    ;;
  Darwin)
    [ "$(uname -m)" = arm64 ] || { echo 'macOS Agent 仅支持 ARM64' >&2; exit 1; }
    STAGING_BASE=/opt/apsp
    ;;
  FreeBSD) STAGING_BASE=/opt/apsp ;;
  *) echo '此入口支持 Linux、macOS 和 FreeBSD；Windows 请使用 PowerShell 入口' >&2; exit 1 ;;
esac
case "$(uname -m)" in x86_64|amd64|aarch64|arm64) ;; *) echo '此接入入口仅支持 AMD64 和 ARM64' >&2; exit 1 ;; esac

# /run and system temporary volumes can be noexec; /opt is the Agent executable volume.
protected_directory() {
  PROTECTED_CHECK=$1
  while :; do
    [ -d "$PROTECTED_CHECK" ] && [ ! -L "$PROTECTED_CHECK" ] || { echo '安装临时目录与父目录必须是普通目录' >&2; exit 1; }
    if [ "$PLATFORM" = Linux ]; then
      PROTECTED_OWNER=$(stat -c '%u' "$PROTECTED_CHECK")
      PROTECTED_MODE=$(stat -c '%a' "$PROTECTED_CHECK")
    else
      PROTECTED_OWNER=$(/usr/bin/stat -f '%u' "$PROTECTED_CHECK")
      PROTECTED_MODE=$(/usr/bin/stat -f '%Lp' "$PROTECTED_CHECK")
    fi
    [ "$PROTECTED_OWNER" = 0 ] && [ "$((0$PROTECTED_MODE & 022))" = 0 ] || { echo "安装临时目录与父目录必须由 root 保护，不能由其他账户写入：$PROTECTED_CHECK（属主 $PROTECTED_OWNER，权限 $PROTECTED_MODE）" >&2; exit 1; }
    [ "$PROTECTED_CHECK" != / ] || break
    PROTECTED_CHECK=$(dirname "$PROTECTED_CHECK")
  done
}
EXISTING_PARENT=$STAGING_BASE
while [ ! -e "$EXISTING_PARENT" ] && [ ! -L "$EXISTING_PARENT" ]; do EXISTING_PARENT=$(dirname "$EXISTING_PARENT"); done
protected_directory "$EXISTING_PARENT"
if [ ! -e "$STAGING_BASE" ] && [ ! -L "$STAGING_BASE" ]; then
  (umask 022; mkdir -p "$STAGING_BASE")
  # An inherited default ACL ignores the umask; tighten only what was just created.
  chmod 755 "$STAGING_BASE"
fi
protected_directory "$STAGING_BASE"
STAGING=$(mktemp -d "$STAGING_BASE/apsp-bootstrap.XXXXXX")
cleanup() { rm -rf "$STAGING"; }
trap cleanup EXIT
trap 'exit 130' INT
trap 'exit 143' HUP TERM
PYTHON=python3
MINISIGN=minisign

if [ "$PLATFORM" = Darwin ]; then
  # Use independently pinned upstream tools instead of running Homebrew as root.
  PYTHON=/Library/Frameworks/Python.framework/Versions/3.13/bin/python3.13
  if [ ! -x "$PYTHON" ]; then
    /usr/bin/curl --fail --silent --show-error --proto '=https' --noproxy '*' --connect-timeout 20 --max-time 600 --max-filesize 100000000 https://www.python.org/ftp/python/3.13.16/python-3.13.16-macos11.pkg -o "$STAGING/python.pkg"
    printf '%s  %s\n' 30666509020b4da0dd8bc2e773255f34d76b7bb80b66960a928d5f6daa0192d7 "$STAGING/python.pkg" | /usr/bin/shasum -a 256 -c - >/dev/null
    /usr/sbin/pkgutil --check-signature "$STAGING/python.pkg" >/dev/null
    /usr/sbin/installer -pkg "$STAGING/python.pkg" -target /
  fi
  # Resolve the fixed official Framework alias, then execute only its protected real path.
  PYTHON_LINKS=0
  while [ -L "$PYTHON" ]; do
    PYTHON_LINKS=$((PYTHON_LINKS + 1))
    [ "$PYTHON_LINKS" -le 16 ] || { echo 'Python Framework 链接过多' >&2; exit 1; }
    PYTHON_PARENT=$(dirname "$PYTHON")
    PYTHON_LINK=$(/usr/bin/readlink "$PYTHON")
    case "$PYTHON_LINK" in /*) PYTHON=$PYTHON_LINK ;; *) PYTHON="$PYTHON_PARENT/$PYTHON_LINK" ;; esac
  done
  PYTHON_PARENT=$(cd -P "$(dirname "$PYTHON")" && pwd -P)
  PYTHON="$PYTHON_PARENT/$(basename "$PYTHON")"
  PYTHON_CHECK=$PYTHON
  while :; do
    PYTHON_OWNER=$(/usr/bin/stat -f '%u' "$PYTHON_CHECK")
    PYTHON_MODE=$(/usr/bin/stat -f '%Lp' "$PYTHON_CHECK")
    [ "$PYTHON_OWNER" = 0 ] && [ "$((0$PYTHON_MODE & 022))" = 0 ] && [ ! -L "$PYTHON_CHECK" ] || { echo 'Python Framework 与父目录必须由 root 保护' >&2; exit 1; }
    [ "$PYTHON_CHECK" != / ] || break
    PYTHON_CHECK=$(dirname "$PYTHON_CHECK")
  done
  /usr/bin/curl --fail --silent --show-error --location --proto '=https' --proto-redir '=https' --noproxy '*' --connect-timeout 20 --max-time 120 --max-filesize 1000000 https://github.com/jedisct1/minisign/releases/download/0.12/minisign-0.12-macos.zip -o "$STAGING/minisign.zip"
  printf '%s  %s\n' 89000b19535765f9cffc65a65d64a820f433ef6db8020667f7570e06bf6aac63 "$STAGING/minisign.zip" | /usr/bin/shasum -a 256 -c - >/dev/null
  "$PYTHON" -I - "$STAGING/minisign.zip" "$STAGING/minisign" <<'PY'
import hashlib, pathlib, stat, sys, zipfile
with zipfile.ZipFile(sys.argv[1]) as archive:
    if set(archive.namelist()) != {'minisign', '._minisign'}:
        raise SystemExit('minisign 官方归档包含非预期文件')
    member = archive.getinfo('minisign')
    if member.file_size != 180736 or member.is_dir() or stat.S_ISLNK(member.external_attr >> 16):
        raise SystemExit('minisign 官方归档文件无效')
    data = archive.read(member)
    if hashlib.sha256(data).hexdigest() != 'd41cde458303d45c95b00473e2455a7f45f95b550931f1f0cc98ef1f61b2a8ff':
        raise SystemExit('minisign 官方可执行文件摘要不匹配')
    target = pathlib.Path(sys.argv[2])
    target.write_bytes(data)
    target.chmod(0o700)
PY
  MINISIGN="$STAGING/minisign"
  /usr/bin/security find-certificate -a -p /System/Library/Keychains/SystemRootCertificates.keychain > "$STAGING/system-ca.pem"
  [ -s "$STAGING/system-ca.pem" ] || { echo '无法读取 macOS 系统信任根证书' >&2; exit 1; }
  SSL_CERT_FILE="$STAGING/system-ca.pem"
  export SSL_CERT_FILE
else

NEEDS_PACKAGES=0
TOOLS='python3'
if [ "$PLATFORM" = Linux ]; then
  TOOLS="$TOOLS install getent cmp mv seq"
  mv --version >/dev/null 2>&1 || NEEDS_PACKAGES=1
  if { ! command -v useradd >/dev/null && ! command -v adduser >/dev/null; } || { ! command -v groupadd >/dev/null && ! command -v addgroup >/dev/null; }; then
    NEEDS_PACKAGES=1
  fi
else
  TOOLS="$TOOLS minisign"
fi
for tool in $TOOLS; do
  command -v "$tool" >/dev/null || NEEDS_PACKAGES=1
done
if [ "$NEEDS_PACKAGES" = 1 ]; then
  printf '%s\n' '正在通过系统软件源准备 Python、minisign 和安装工具。'
  if command -v apt-get >/dev/null; then
    apt-get update
    DEBIAN_FRONTEND=noninteractive apt-get install -y --no-install-recommends python3 ca-certificates coreutils libc-bin passwd
  elif command -v apk >/dev/null; then
    apk add --no-cache python3 ca-certificates coreutils musl-utils
    if { ! command -v useradd >/dev/null && ! command -v adduser >/dev/null; } || { ! command -v groupadd >/dev/null && ! command -v addgroup >/dev/null; }; then
      apk add --no-cache shadow || {
        echo 'Alpine 缺少 adduser/addgroup 且无法安装 shadow，请在 /etc/apk/repositories 启用对应版本的官方 community 软件源后重试' >&2
        exit 1
      }
    fi
  elif command -v dnf >/dev/null; then
    dnf install -y python3 ca-certificates coreutils glibc-common shadow-utils
  elif command -v yum >/dev/null; then
    yum install -y python3 ca-certificates coreutils glibc-common shadow-utils
  elif [ "$PLATFORM" = FreeBSD ] && command -v pkg >/dev/null; then
    ASSUME_ALWAYS_YES=yes pkg bootstrap -f
    pkg install -y python3 minisign ca_root_nss
  else
    echo '无法自动准备安装工具：需要系统 apt-get、apk、dnf、yum 或 FreeBSD pkg 软件源' >&2
    exit 1
  fi
fi
for tool in $TOOLS; do
  command -v "$tool" >/dev/null || { echo "系统软件源未提供所需工具: $tool" >&2; exit 1; }
done
fi
"$PYTHON" -I - "$STAGING" <<'APSP_BOOTSTRAP_FILES_PY'
import base64, hashlib, json, lzma, os, pathlib, sys
manifest = {'LICENSE': {'size': 34523, 'sha256': '0d96a4ff68ad6d4b6f1f30f713b18d5184912ba8dd389f86aa7710db079abcb0'}, 'crates/observability/upstream/ipquality/SOURCE.md': {'size': 7018, 'sha256': 'afb8e9103f5ed397d30083aea3e8b675868e40677e9caef670b66410cc7ae0fd'}, 'crates/observability/upstream/ipquality/runner.py': {'size': 15131, 'sha256': '9b795e5e7536e810558e69b67904a3f184516c993e697f2244087e209ad85dda'}, 'crates/observability/upstream/ipquality/source-helper.py': {'size': 9372, 'sha256': '4b3636f7480fe6fe8eda437a8eebfabbb094bb261277c281004c3e666cfcc46c'}, 'crates/observability/upstream/ipquality/source-lock.json': {'size': 996, 'sha256': 'ded8f7a8f37644dbb80844883ad101205846a2e12b4dc3e3dc0c03f1854e815d'}, 'crates/observability/upstream/ipquality/source-policy.py': {'size': 15391, 'sha256': 'c8205aea651ad6530e651db958cb558d7014a79ad1efbfc1a6e81517ff4247c0'}, 'crates/observability/upstream/ipquality/transport.py': {'size': 33325, 'sha256': 'ddd89edf5d9c1254d13e37e1b81eef604cf76aad42a4f952c4e53286132efdd8'}, 'crates/observability/upstream/nodequality/access-policy.py': {'size': 12709, 'sha256': '7520a325667855eaa9ab3535a3d65045e9a6ee006b6eae39e1cf2653908c4b2b'}, 'crates/observability/upstream/nodequality/browser-policy.py': {'size': 3058, 'sha256': 'a7d0f1bdfc9f2002b20770ef43eee3f352897ab70178e1f2a3ff9858fffc8f56'}, 'crates/observability/upstream/nodequality/chroot-shim.sh': {'size': 574, 'sha256': 'af7f0e7e143b8dc0d03a7501382304a06caab96f2dffbbf08a61a55f8c686b1f'}, 'crates/observability/upstream/nodequality/curl-shim.sh': {'size': 1299, 'sha256': 'ce26a405e165e9521353f7c573cee0480403b497a4467789747e841470ebf1f3'}, 'crates/observability/upstream/nodequality/daily.py': {'size': 6347, 'sha256': '9dd9bc0661e94e4cae15be3f18fe242d6a621ab71bdc92726f6f964c7e3e0120'}, 'crates/observability/upstream/nodequality/data-policy.py': {'size': 3873, 'sha256': '0115f90f8ce521eab1472d8426b8f8dfbf1fefca427ae0fdfd557b346a8fdab3'}, 'crates/observability/upstream/nodequality/dependency-policy.py': {'size': 5626, 'sha256': 'e8828b3929aaeabd7b0fc615205998f9e21a6403fa96a9400bc81fe06e02f9f2'}, 'crates/observability/upstream/nodequality/execution-admission.json': {'size': 1168, 'sha256': '2c386a1c2348f28cd27cd0d25ef9d8aefc012124701f04c416d4f5c5e368a7f8'}, 'crates/observability/upstream/nodequality/exit-observer.sh': {'size': 728, 'sha256': '2eaec5cbada14c55b9d329443bb89746029d0eaebf08e05d9c91abde99333d97'}, 'crates/observability/upstream/nodequality/historical-native-r1/native-report.py': {'size': 14680, 'sha256': '5034e8d27f4b91172f06c6149d3e8e9653c67d5116721bc00a56efa2be66320f'}, 'crates/observability/upstream/nodequality/historical-native-r1/native-runner.sh.tmpl': {'size': 10995, 'sha256': '9d24b242669b3b6152e294a00e07d8396462c576ed82be5500b479e723f1584f'}, 'crates/observability/upstream/nodequality/historical-r19/report.py': {'size': 12293, 'sha256': '60dfa274ef3e0687ee74f0ad4e8bbe7ebab0472628cc671d57d3517fe2c5591f'}, 'crates/observability/upstream/nodequality/historical-r19/rootfs.py': {'size': 24151, 'sha256': '215d2e5367c6640399cfc8954aa5b42c18c159ba341e450af397024b3ae0345e'}, 'crates/observability/upstream/nodequality/historical-r19/runner.sh.tmpl': {'size': 9767, 'sha256': 'b2842d48ad9df0c70734500ba80f9cfae269bee89c18c0877f007a43f4aece79'}, 'crates/observability/upstream/nodequality/ip-score-policy.py': {'size': 4701, 'sha256': '9ef1a5cf9a6c442d5abdf8ee91f2b42458c940a49f74c6d13a649cc5fb2ce303'}, 'crates/observability/upstream/nodequality/loader-policy.py': {'size': 3129, 'sha256': 'e2b9b633905b4af61efe4c69dc984e8b76a3a0de650bebfcdd07b473f4a2df59'}, 'crates/observability/upstream/nodequality/native-browser-policy.py': {'size': 3058, 'sha256': '0b4ad0d200bae6b6919f5ae3d2b69b1c46c7f388dc29f4d4f25e95d6ec3c9723'}, 'crates/observability/upstream/nodequality/native-netflix-policy.py': {'size': 10564, 'sha256': '9b1a56cd71af3370d990d89be5c1a937a8de6f788f1e2da2e86738e42db0cd22'}, 'crates/observability/upstream/nodequality/native-report.py': {'size': 24034, 'sha256': 'd0189e298c94d7a2da100dfe6d0d351e54ca79edb4b369f5f6c1d307c13d3d13'}, 'crates/observability/upstream/nodequality/native-source-helper.py': {'size': 24062, 'sha256': '39bc914c1af680ecf06cc476d267773ec7d0f2662d264d2b0e37c59515ad4888'}, 'crates/observability/upstream/nodequality/netflix-policy.py': {'size': 5785, 'sha256': '38b077bc7430fae4fba6eaa6570f738333a12c267e1c329ac92a86d9148cd8d5'}, 'crates/observability/upstream/nodequality/node-query.py': {'size': 20521, 'sha256': '2e9db69b2b6207d98624ebf4a77ea0e3bcc5d6cd077d30326129d195cd0071ba'}, 'crates/observability/upstream/nodequality/official-ip.py': {'size': 15529, 'sha256': 'b0de7a19cbe01a3cd6a1f4c00902bf97f36e99fce63933c95064eb44b2867be8'}, 'crates/observability/upstream/nodequality/openai-policy.py': {'size': 3487, 'sha256': 'b7390471a552dee857414214dec3d5c5f5870caab27a357ef4b66780474ded7b'}, 'crates/observability/upstream/nodequality/public-access-policy.py': {'size': 5164, 'sha256': '604c29102c145a38282d779e6236871198ecec096adde1593ad6b0da8043b846'}, 'crates/observability/upstream/nodequality/query-policy.py': {'size': 5131, 'sha256': 'fe459061e903f815369f637a42e5197661f160c0ec2a1b24915317a37e68453b'}, 'crates/observability/upstream/nodequality/ranking-policy.py': {'size': 2355, 'sha256': '4b6bdcfb8f03268479fd5eb70a00cdebb25b8fcab513dfc62bff226dd450d6c8'}, 'crates/observability/upstream/nodequality/report-policy.py': {'size': 4338, 'sha256': '468311a213e820f920a9f556dfaaf6883002232d459c9e36d2622db2d7b43b26'}, 'crates/observability/upstream/nodequality/report.py': {'size': 23892, 'sha256': '278c8b33ac913ecc232ed36a237864d63d21087967646b9e1e066c3db9d12524'}, 'crates/observability/upstream/nodequality/rootfs.py': {'size': 24331, 'sha256': 'dbcc9911f4494bbf6503b4b2bcff784105138ac6deb6a8e0cc581ad2e7a80766'}, 'crates/observability/upstream/nodequality/source-helper.py': {'size': 22115, 'sha256': '7c92d6d40c9b6e0b7634533c5058e27d9c93a781dd4395327e3cf8d376f887ff'}, 'crates/observability/upstream/nodequali